 * returned object.
 *
 * @param {string} prefix - The required prefix.
 * @param {object} [extraParams={}] - Optional extra fields to merge.
 * @returns {object} Validation descriptor.
 */
zod.z.startsWith = function (prefix, extraParams = {}) {
    return {
        check: 'string_format',
        format: 'starts_with',
        prefix,
        ...extraParams,
    };
};

